2191:function Resolve-EffortPlan {
2192:    param($Identity, [string]$Requested, [string]$Native = '')
2193:    $plan = [pscustomobject]@{ Requested = $Requested; Sent = ''; Mapping = ''; Caps = $script:EffortCapsVersion; Basis = ''; Error = '' }
2194:    if ($Native) {
2195:        $plan.Requested = $Native; $plan.Sent = $Native; $plan.Mapping = 'native'; $plan.Basis = '-NativeEffort, sent verbatim'
2196:        return $plan
2197:    }
2198:    $hostName = [string]$Identity.HostName
2199:    $model = [string]$Identity.Model
2200:    $cap = $null
2201:    if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) { $cap = $script:EffortCaps[$hostName] }
2202:    if (-not $cap) {
2203:        $hostLabel = if ($hostName) { $hostName } else { 'unknown-host' }
2204:        $declared = @($script:EffortCaps.Keys | Sort-Object) -join ', '
2205:        $plan.Error = "no effort vocabulary declared for $hostLabel ($($script:EffortCapsVersion) declares $declared); pass -NativeEffort <value> to send a value verbatim"
2206:        return $plan
2207:    }
2208:    if (($null -ne $cap.Models) -and (($Identity.ModelSource -eq 'unknown') -or -not ($cap.Models -ccontains $model))) {
2209:        $plan.Error = "no effort vocabulary declared for model '$model' on $hostName ($($script:EffortCapsVersion) declares: $($cap.Models -join ', ')); pass -NativeEffort <value> to send a value verbatim"
2210:        return $plan
2211:    }
2212:    $v = $script:EffortVocabularies[$cap.Vocabulary]
2213:    $plan.Sent = $v.Map[$Requested]
2214:    $plan.Mapping = $v.Mapping
2215:    $plan.Basis = if ($null -eq $cap.Models) { "$($script:EffortCapsVersion): $hostName, any model" } else { "$($script:EffortCapsVersion): $hostName, $model" }
2216:    return $plan
2217:}
