2219:# ----------------------------------------------------------------------------- peak windows
2220:#
2221:# CODEX_CONSULT_PEAK_<PROVIDER> = "<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>" (the provider
2222:# name upper-cased, every character outside A-Z 0-9 replaced by _), e.g.
2223:# CODEX_CONSULT_PEAK_ZAI="Mon-Fri 14:00-18:00 +08:00". Days: *, a day (Mon), a range
2224:# (Mon-Fri; it may wrap: Fri-Mon) or a comma list of those. Optional
2225:# CODEX_CONSULT_PEAK_<PROVIDER>_EXCEPT = comma-separated YYYY-MM-DD or
2226:# YYYY-MM-DD..YYYY-MM-DD: those calendar dates (in the schedule's offset) are off-peak all
2227:# day. Evaluated ONCE at launch in the fixed offset: start inclusive, end exclusive (24:00
2228:# = midnight); an overnight window (start > end) spans midnight and its day check applies
2229:# to the day it STARTED. peak = $true | $false; $null = no schedule (unknown). A long
2230:# consultation that starts off-peak may still run into the window.
2231:$script:DayNames = @('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat')
2232:
2233:# The clock of the peak evaluations. TEST HOOK: CODEX_CONSULT_NOW = one or more ISO
2234:# timestamps with an offset, comma-separated; the k-th evaluation of a run uses the k-th
2235:# (the last one repeats), so a test can put the early check off-peak and the launch-time
2236:# check inside the window. Unset: the system clock. { Now (DateTimeOffset); Iso; FromEnv;
2237:# Error }.
2238:$script:ConsultClockCalls = 0
2239:function Get-ConsultClock {
2240:    $raw = [string]$env:CODEX_CONSULT_NOW
2241:    $call = $script:ConsultClockCalls
2242:    $script:ConsultClockCalls++
2243:    if (-not $raw.Trim()) {
2244:        $n = [DateTimeOffset]::Now
2245:        return [pscustomobject]@{ Now = $n; Iso = $n.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $false; Error = '' }
2246:    }
2247:    $items = @($raw.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2248:    $parsed = New-Object System.Collections.Generic.List[DateTimeOffset]
2249:    foreach ($item in $items) {
2250:        $dto = [DateTimeOffset]::MinValue
2251:        if ($item -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?([+-][0-9]{2}:[0-9]{2}|Z)$' -or -not [DateTimeOffset]::TryParse($item, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dto)) {
2252:            return [pscustomobject]@{ Now = $null; Iso = ''; FromEnv = $true; Error = "CODEX_CONSULT_NOW='$raw' is malformed: bad token '$item' (a test hook: ISO timestamps with an offset, e.g. 2026-09-24T13:59:59+08:00, comma-separated)" }
2253:        }
2254:        $parsed.Add($dto)
2255:    }
2256:    $pick = $parsed[[Math]::Min($call, $parsed.Count - 1)]
2257:    return [pscustomobject]@{ Now = $pick; Iso = $pick.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $true; Error = '' }
2258:}
2259:
2260:# Get-PeakStatus at the clock's current reading; adds EvaluatedAt and marks a peak_source
2261:# 'env (CODEX_CONSULT_NOW)' when the test hook set the time. Error covers both inputs.
2262:function Get-PeakStatusNow {
2263:    param([string]$Provider)
2264:    $clock = Get-ConsultClock
2265:    if ($clock.Error) { return [pscustomobject]@{ Peak = $null; Schedule = ''; Source = 'none'; Variable = ''; Local = ''; Detail = ''; Error = $clock.Error; EvaluatedAt = '' } }
2266:    $st = Get-PeakStatus -Provider $Provider -UtcNow $clock.Now.UtcDateTime
2267:    if ($clock.FromEnv -and $st.Source -eq 'env') { $st.Source = 'env (CODEX_CONSULT_NOW)' }
2268:    $st | Add-Member -NotePropertyName 'EvaluatedAt' -NotePropertyValue $clock.Iso
2269:    return $st
2270:}
