2336:# { Intervals (list of @(start, end) dates, inclusive); Error }. Ranges are kept as
2337:# intervals - any length, never expanded; only end < start is refused.
2338:function ConvertFrom-PeakExceptions {
2339:    param([string]$Text, [string]$VarName)
2340:    $list = New-Object System.Collections.Generic.List[object]
2341:    $r = [pscustomobject]@{ Intervals = $list; Error = '' }
2342:    $format = 'expected comma-separated YYYY-MM-DD or YYYY-MM-DD..YYYY-MM-DD'
2343:    foreach ($raw in ([string]$Text).Split(',')) {
2344:        $item = $raw.Trim()
2345:        if (-not $item) { continue }
2346:        $parts = @($item -split '\.\.')
2347:        $parsed = New-Object System.Collections.Generic.List[datetime]
2348:        foreach ($p in $parts) {
2349:            $dt = [datetime]::MinValue
2350:            if ($p -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' -or -not [datetime]::TryParseExact($p, 'yyyy-MM-dd', $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) {
2351:                $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format)"; return $r
2352:            }
2353:            $parsed.Add($dt.Date)
2354:        }
2355:        if ($parsed.Count -gt 2 -or ($parsed.Count -eq 2 -and $parsed[1] -lt $parsed[0])) {
2356:            $r.Error = "$VarName='$Text' is malformed: bad token '$item' ($format; a range must not run backwards)"; return $r
2357:        }
2358:        $list.Add(@($parsed[0], $parsed[$parsed.Count - 1]))
2359:    }
2360:    return $r
2361:}
