2458:
2459:# `<launcher> login status` with a timeout; stdout and stderr are both read (the status
2460:# line may come on either). { State ok|missing|unknown; Reason; Detail }.
2461:function Get-CodexLoginStatus {
2462:    param([string]$Launcher, [int]$TimeoutSec = 15)
2463:    if (-not $Launcher) { return (New-CredentialResult 'unknown' 'codex CLI not found, `codex login status` could not run') }
2464:    $p = $null
2465:    try {
2466:        $psi = New-Object System.Diagnostics.ProcessStartInfo
2467:        $psi.FileName = $Launcher
2468:        $psi.Arguments = 'login status'
2469:        $psi.UseShellExecute = $false
2470:        $psi.CreateNoWindow = $true
2471:        $psi.RedirectStandardInput = $true
2472:        $psi.RedirectStandardOutput = $true
2473:        $psi.RedirectStandardError = $true
2474:        $p = [System.Diagnostics.Process]::Start($psi)
2475:    } catch {
2476:        return (New-CredentialResult 'unknown' "``codex login status`` could not be started ($(ConvertTo-OneLine $_.Exception.Message))")
2477:    }
2478:    try {
2479:        try { $p.StandardInput.Close() } catch { }
2480:        $outTask = $p.StandardOutput.ReadToEndAsync()
2481:        $errTask = $p.StandardError.ReadToEndAsync()
2482:        if (-not $p.WaitForExit($TimeoutSec * 1000)) {
2483:            $null = Stop-ProcessTree -Process $p
2484:            return (New-CredentialResult 'unknown' "``codex login status`` did not finish within $TimeoutSec s")
2485:        }
2486:        $p.WaitForExit()
2487:        $null = $outTask.Wait(5000)
2488:        $null = $errTask.Wait(5000)
2489:        $lines = @((([string]$outTask.Result) + "`n" + ([string]$errTask.Result)) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2490:        $loggedIn = @($lines | Where-Object { $_ -cmatch 'Logged in' }) | Select-Object -First 1
2491:        if ($p.ExitCode -eq 0 -and $loggedIn) { return (New-CredentialResult 'ok' $loggedIn) }
2492:        $first = if ($lines.Count -gt 0) { $lines[0] } else { "exit $($p.ExitCode)" }
2493:        return (New-CredentialResult 'missing' $first)
2494:    } finally {
2495:        $p.Dispose()
2496:    }
2497:}
