2499:# Credentials of a provider: $Table is its [model_providers.<name>] table object ($null for
2500:# the built-in openai without one). $LoginCache (a hashtable) avoids running
2501:# `login status` twice in one listing.
2502:function Get-ProviderCredential {
2503:    param([string]$Name, $Table, [string]$Launcher, [hashtable]$LoginCache = $null, [int]$TimeoutSec = 15)
2504:    $openaiAuth = ($Name -ceq 'openai')
2505:    if (-not $openaiAuth -and $Table) {
2506:        $ro = $Table.Entries['requires_openai_auth']
2507:        if ($Table.Entries.ContainsKey('requires_openai_auth') -and $ro.Supported -and $ro.Kind -eq 'boolean' -and $ro.Value -ceq 'true') { $openaiAuth = $true }
2508:    }
2509:    if ($openaiAuth) {
2510:        if ($LoginCache -and $LoginCache.ContainsKey('login')) { return $LoginCache['login'] }
2511:        $r = Get-CodexLoginStatus -Launcher $Launcher -TimeoutSec $TimeoutSec
2512:        if ($LoginCache) { $LoginCache['login'] = $r }
2513:        return $r
2514:    }
2515:    if (-not $Table) { return (New-CredentialResult 'unknown' "no [model_providers.$Name] table") }
2516:    $ek = Get-TomlString -Table $Table -Key 'env_key'
2517:    $bt = Get-TomlString -Table $Table -Key 'experimental_bearer_token'
2518:    $envName = ''
2519:    if ($ek.Present -and -not $ek.Reason) { $envName = $ek.Value.Trim() }
2520:    if ($envName) {
2521:        $v = [Environment]::GetEnvironmentVariable($envName)
2522:        if ($v -and $v.Trim()) { return (New-CredentialResult 'ok' "env $envName set") }
2523:    }
2524:    if ($bt.Present -and -not $bt.Reason -and $bt.Value) { return (New-CredentialResult 'ok' 'bearer token in config') }
2525:    if ($envName) { return (New-CredentialResult 'missing' "env $envName not set") }
2526:    return (New-CredentialResult 'missing' 'no env_key/bearer token in the table')
2527:}
