2529:# Classes of a provider failure, tried in this order (case-insensitive).
2530:$script:FailureClassPatterns = [ordered]@{
2531:    'auth'       = '(?i)\b40[13]\b|unauthori[sz]ed|forbidden|invalid[ _]api[ _]key|authentication|\bauth'
2532:    'quota'      = '(?i)usage limit|quota|rate limit|\b429\b|insufficient balance|too many requests|credits? exhausted|credit balance|payment required|\b402\b|token plan|plan exhausted|billing'
2533:    'capability' = '(?i)not supported|unsupported|feature_not_supported|json_schema'
2534:    'transport'  = '(?i)timeout|timed out|connection|econn|enotfound|\bdns\b|\btls\b|certificate|\b50[234]\b|network'
2535:}
2536:$script:BuiltinOpenAiFingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes('cc-provider-v1|builtin:openai'))
2537:
2538:# auth | quota | capability | transport | unknown
2539:function Get-ProviderFailureClass {
2540:    param([string]$Message)
2541:    foreach ($k in $script:FailureClassPatterns.Keys) {
2542:        if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
2543:    }
2544:    return 'unknown'
2545:}
2546:
2547:# The provider's own error inside a failure text: an SSE payload `data:{"error":{...}}`
2548:# (MiMo sends its rejections that way) or a bare `{"error":{...}}` -> error.message and
2549:# error.code; otherwise the text itself. { Code; Message }.
2550:function ConvertFrom-ProviderErrorText {
2551:    param([string]$Text)
2552:    $r = [pscustomobject]@{ Code = ''; Message = (ConvertTo-OneLine $Text) }
2553:    if (-not $Text) { return $r }
2554:    $candidates = New-Object System.Collections.Generic.List[string]
2555:    foreach ($m in [regex]::Matches($Text, '(?m)data:\s*(\{.*\})\s*$')) { $candidates.Add($m.Groups[1].Value) }
2556:    $at = $Text.IndexOf('{"error"')
2557:    if ($at -ge 0) { $candidates.Add($Text.Substring($at).Trim()) }
2558:    foreach ($json in $candidates) {
2559:        $o = $null
2560:        try { $o = ConvertFrom-Json -InputObject $json } catch { continue }
2561:        $e = Get-PropertyValue $o 'error' $null
2562:        if ($null -eq $e) { continue }
2563:        if ($e -is [string]) { $r.Message = ConvertTo-OneLine $e; return $r }
2564:        $msg = [string](Get-PropertyValue $e 'message' '')
2565:        if ($msg) { $r.Message = ConvertTo-OneLine $msg }
2566:        $r.Code = [string](Get-PropertyValue $e 'code' '')
2567:        if (-not $r.Code) { $r.Code = [string](Get-PropertyValue $e 'type' '') }
2568:        return $r
2569:    }
2570:    return $r
2571:}
2572:
2573:# The ledger's provider_failure of a failed run: { class; code; message (<= 200); when }.
2574:# $Texts: the evidence in order of preference (the event-stream error, stderr, the bridge
2575:# outcome); the first that holds a provider error payload wins, else the first non-empty.
2576:function New-ProviderFailure {
2577:    param([string[]]$Texts)
2578:    $chosen = $null
2579:    foreach ($t in @($Texts | Where-Object { $_ -and $_.Trim() })) {
2580:        $p = ConvertFrom-ProviderErrorText -Text $t
2581:        if ($p.Code -or ($t.IndexOf('{"error"') -ge 0)) { $chosen = $p; break }
2582:        if (-not $chosen) { $chosen = $p }
2583:    }
2584:    if (-not $chosen) { $chosen = [pscustomobject]@{ Code = ''; Message = '' } }
2585:    $msg = [string]$chosen.Message
2586:    if ($msg.Length -gt 200) { $msg = $msg.Substring(0, 200) }
2587:    return [pscustomobject]@{
2588:        class   = (Get-ProviderFailureClass "$($chosen.Code) $($chosen.Message)")
2589:        code    = [string]$chosen.Code
2590:        message = $msg
2591:        when    = (Get-IsoTimestamp)
2592:    }
2593:}
