2597:function Read-AllTaskConsults {
2598:    param([string]$CollabRoot)
2599:    $all = New-Object System.Collections.Generic.List[object]
2600:    if (-not $CollabRoot -or -not (Test-Path -LiteralPath $CollabRoot -PathType Container)) { return , $all.ToArray() }
2601:    foreach ($dir in @(Get-ChildItem -LiteralPath $CollabRoot -Directory -ErrorAction SilentlyContinue)) {
2602:        $f = Join-Path $dir.FullName 'sessions.json'
2603:        if (-not (Test-Path -LiteralPath $f -PathType Leaf)) { continue }
2604:        try {
2605:            $data = ConvertFrom-Json -InputObject (Read-SharedText -Path $f)
2606:            foreach ($c in @(Get-PropertyValue (Get-PropertyValue $data 'codex' $null) 'consults' @())) { if ($null -ne $c) { $all.Add($c) } }
2607:        } catch { }
2608:    }
2609:    return , $all.ToArray()
2610:}
