2612:function ConvertTo-WhenOffset {
2613:    param($Value)
2614:    if ($Value -is [DateTimeOffset]) { return $Value }
2615:    if ($Value -is [datetime]) { return [DateTimeOffset]$Value }
2616:    $at = [DateTimeOffset]::MinValue
2617:    if ([DateTimeOffset]::TryParse([string]$Value, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$at)) { return $at }
2618:    return $null
