2620:
2621:# Health of one ENDPOINT (provider_fingerprint - never the alias) from the ledgers of all
2622:# tasks. Entries recorded before 0.3.0 count as the built-in openai endpoint; entries with
2623:# an unresolved identity (empty fingerprint) are ignored. A failure's class comes from its
2624:# provider_failure, else (older entries) from its bridge_outcome. Newest wins: a later
2625:# successful run clears an earlier auth or quota failure.
2626:#   Auth         the newest of {success, auth failure} is an auth failure <= 24 h old
2627:#   Quota        the newest of {success, quota failure} is a quota failure <= 60 min old
2628:#   LastLimit    the newest quota failure <= 24 h old (informational)
2629:#   LastFailure  the newest failure of any class <= 24 h old (informational)
2630:# Each is $null or { Class; Code; Message; When; AgeMinutes }.
2631:function Get-EndpointHealth {
2632:    param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
2633:    $h = [pscustomobject]@{ Auth = $null; Quota = $null; LastLimit = $null; LastFailure = $null }
2634:    if (-not $Fingerprint) { return $h }
2635:    $records = New-Object System.Collections.Generic.List[object]
2636:    foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
2637:        $rev = Get-PropertyValue $c 'reviewer' $null
2638:        $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
2639:        if (-not $fp -or $fp -ne $Fingerprint) { continue }
2640:        $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
2641:        if (-not $outcome) { continue }
2642:        $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
2643:        if ($null -eq $at) { continue }
2644:        $age = ($UtcNow - $at.UtcDateTime).TotalMinutes
2645:        if ($age -lt -5) { continue }
2646:        $rec = [pscustomobject]@{ At = $at; Ok = ($outcome -eq 'usable reply'); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)) }
2647:        if (-not $rec.Ok) {
2648:            $pf = Get-PropertyValue $c 'provider_failure' $null
2649:            if ($null -ne $pf) {
2650:                $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
2651:                $rec.Code = [string](Get-PropertyValue $pf 'code' '')
2652:                $rec.Message = [string](Get-PropertyValue $pf 'message' '')
2653:            } else {
2654:                # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
2655:                $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
2656:                $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
2657:                $rec.Code = $parsedOutcome.Code
2658:                $rec.Message = $parsedOutcome.Message
2659:            }
2660:            if ($rec.Message.Length -gt 100) { $rec.Message = $rec.Message.Substring(0, 100) }
2661:        }
2662:        $records.Add($rec)
2663:    }
2664:    $sorted = @($records | Sort-Object -Property At -Descending)
2665:    $auth = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'auth' }) | Select-Object -First 1
2666:    if ($auth -and -not $auth.Ok -and $auth.AgeMinutes -le 24 * 60) { $h.Auth = $auth }
2667:    $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
2668:    if ($quota -and -not $quota.Ok -and $quota.AgeMinutes -le 60) { $h.Quota = $quota }
2669:    $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
2670:    $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1

235:function Get-ErrorFromEvents {
236:    param([string]$Path)
237:    $text = Read-SharedText -Path $Path
238:    if (-not $text) { return '' }
239:    $found = ''
240:    foreach ($line in ($text -split "`r?`n")) {
241:        if (-not $line) { continue }
242:        $trimmed = $line.Trim()
243:        if (-not $trimmed.StartsWith('{')) { continue }
244:        $obj = $null
245:        try { $obj = $trimmed | ConvertFrom-Json } catch { continue }
246:        if (-not $obj.PSObject.Properties['type']) { continue }
247:        if ($obj.type -eq 'error' -and $obj.PSObject.Properties['message'] -and $obj.message) {
248:            $found = [string]$obj.message
249:        } elseif ($obj.type -eq 'turn.failed' -and $obj.PSObject.Properties['error']) {
250:            $err = $obj.error
251:            if ($err -and $err.PSObject.Properties['message'] -and $err.message) {
252:                $found = [string]$err.message
253:            }
254:        }
255:    }
256:    return ($found -replace '\s+', ' ').Trim()
257:}
